from pathlib import Path
p=Path('output/mascotas-svg-v3')
def svg(n,defs,body):
 (p/f'{n}.svg').write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 362 362" role="img" aria-label="{n}"><defs>{defs}</defs>{body}</svg>''')
def grad(id,a,b):
 return f'<linearGradient id="{id}" x1="0" y1="0" x2=".8" y2="1"><stop stop-color="{a}"/><stop offset="1" stop-color="{b}"/></linearGradient>'
